function render(){if(analyticsMap){analyticsMap.remove();analyticsMap=null}current=(location.hash.slice(1)||'home').split('?')[0];if(current==='login'){ $('#screen').innerHTML=loginPage();header();bindLogin();return}if(current==='home'){$('#screen').innerHTML=home();header();return}if(current==='about'||current==='contact'){$('#screen').innerHTML=`<div class="about-page"><div class="eyebrow">VASUDHA</div><h1 style="font:800 30px var(--serif)">${current==='about'?'About VASUDHA':'Contact'}</h1><p class="muted" style="line-height:1.7;max-width:650px">VASUDHA is a geospatial watershed planning interface. Area maps and reports use the boundary and mapped features you select from OpenStreetMap. Coordinator uploads supply project intervention sites and geotagged field photos. Remote sensing measurements require separate verified datasets.</p><a class="btn primary" href="#explorer">Open Watershed Explorer →</a></div>`;header();return}if(['explorer','drainage','vegetation','interventions'].includes(current))$('#screen').innerHTML=mapPage();else if(current==='photos')$('#screen').innerHTML=photosPage();else if(current==='detail'||current==='trenching')$('#screen').innerHTML=detailPage();else if(current==='report')$('#screen').innerHTML=reportPage();else if(['analytics',...analyses.map(a=>a[0])].includes(current))$('#screen').innerHTML=analytics();else{$('#screen').innerHTML=home();current='home'}header();bindCommon();if($('#main-map'))initMap($('#main-map'));if($('#analytics-map')||$('#report-map'))initAnalyticsMap();if($('#gallery-map'))initGalleryMap($('#gallery-map'));if($('#mini-map'))initGalleryMap($('#mini-map'));if(current==='photos')loadPhotos();if(current==='interventions'&&location.hash.includes('detail'))openIntervention(interventions[0]);if((current==='report'||current==='analytics'||analyses.some(x=>x[0]===current))&&selectedArea&&!analyticsFeatures)loadAnalyticsData(selectedArea)}
const originalRender=render;render=function(){const route=(location.hash.slice(1)||'home').split('?')[0];if(!viewer&&!['home','login','about','contact'].includes(route))location.hash='login';originalRender()};
const originalGo=go;go=function(route){if(!viewer&&!['home','login','about','contact'].includes(route))route='login';originalGo(route)};
