function featureColor(layer,f){const p=f.properties||{};if(layer==='drainage')return '#1689d0';if(layer==='water-bodies')return '#08a9df';if(layer==='vegetation')return '#22a76b';return p.category==='farmland'||p.category==='meadow'?'#d2a83d':'#be9b48'}
function styleFeature(layer,f){let cat=f.properties.category||'';let colors=layer==='drainage'?['#162ca0','#368bdf','#8de4f1']:layer==='water-bodies'?['#11a9df']:layer==='vegetation'?cat.includes('Dense')?['#119255']:cat.includes('Moderate')?['#54bb68']:['#b6dc60']:layer==='soil-moisture'?cat.includes('Very High')?['#0875cf']:cat==='High'?['#20aed3']:cat==='Moderate'?['#91ca38']:['#ef7042']:layer==='land-degradation'?cat.includes('High')?['#d94f3e']:cat==='Moderate'?['#eaa238']:['#79bd47']:cat==='Forest'?['#14966a']:cat==='Agriculture'?['#c1d93b']:cat.includes('Built')?['#ed724c']:['#e9b23c'];return {color:layer==='drainage'?colors[(f.properties.order||1)>30?0:(f.properties.order||1)>11?1:2]:colors[0],weight:layer==='drainage'?((f.properties.order||1)>3?3:1.5):1,fillColor:colors[0],fillOpacity:layer==='drainage'?0:.42}}
function interventionColor(t){return t==='Afforestation'?'#1cb875':t==='Check Dam'?'#139cde':t==='Contour Trenching'?'#f1a900':'#ac38c7'}
function setBase(which){if(!map)return;Object.entries(mapLayers.basemaps||{}).forEach(([n,l])=>{if(map.hasLayer(l))map.removeLayer(l);if(n===which)l.addTo(map)});document.querySelectorAll('[data-base]').forEach(b=>b.classList.toggle('active',b.dataset.base===which))}
function setBase(which){for(const [target,layers] of [[map,mapLayers.basemaps||{}],[galleryMap,galleryBasemaps]]){if(!target)continue;Object.entries(layers).forEach(([name,layer])=>{if(target.hasLayer(layer))target.removeLayer(layer);if(name===which)layer.addTo(target)})}document.querySelectorAll('[data-base]').forEach(b=>b.classList.toggle('active',b.dataset.base===which))}
function coordinateInSelectedArea(lat,lng){if(!selectedArea?.geometry||!Number.isFinite(lat)||!Number.isFinite(lng))return false;const inRing=ring=>{let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1],cross=((yi>lat)!==(yj>lat))&&(lng<(xj-xi)*(lat-yi)/((yj-yi)||1e-12)+xi);if(cross)inside=!inside}return inside};const inPolygon=poly=>inRing(poly[0]||[])&&!poly.slice(1).some(inRing),g=selectedArea.geometry;if(g.type==='Polygon')return inPolygon(g.coordinates);if(g.type==='MultiPolygon')return g.coordinates.some(inPolygon);return false}
function geometryAreaKm2(geometry){if(!geometry)return 0;const ringArea=ring=>{let sum=0;for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length];sum+=(b[0]-a[0])*Math.PI/180*(2+Math.sin(a[1]*Math.PI/180)+Math.sin(b[1]*Math.PI/180))}return Math.abs(sum*6371*6371/2)};const polygonArea=poly=>Math.max(0,ringArea(poly[0]||[])-(poly.slice(1).reduce((n,r)=>n+ringArea(r),0)));if(geometry.type==='Polygon')return polygonArea(geometry.coordinates);if(geometry.type==='MultiPolygon')return geometry.coordinates.reduce((n,p)=>n+polygonArea(p),0);return 0}
function geometryLengthKm(geometry){if(!geometry)return 0;const lines=[];const visit=(g)=>{if(!g)return;if(g.type==='LineString')lines.push(g.coordinates);else if(g.type==='MultiLineString')lines.push(...g.coordinates);else if(g.type==='GeometryCollection')g.geometries.forEach(visit)};visit(geometry);let total=0;for(const line of lines)for(let i=1;i<line.length;i++){const [x1,y1]=line[i-1],[x2,y2]=line[i],rad=Math.PI/180,dLat=(y2-y1)*rad,dLon=(x2-x1)*rad,a=Math.sin(dLat/2)**2+Math.cos(y1*rad)*Math.cos(y2*rad)*Math.sin(dLon/2)**2;total+=6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}return total}
function analyticsThemeRows(route,features){const layer={landuse:'landuse',drainageAnalysis:'drainage',vegetationAnalysis:'vegetation',water:'water-bodies'}[route];return layer?features.filter(f=>f.properties.layer===layer):[]}
async function initAnalyticsMap(){if(!window.L)return;const el=$('#analytics-map')||$('#report-map');if(!el)return;if(analyticsMap){analyticsMap.remove();analyticsMap=null}analyticsMap=L.map(el,{zoomControl:true,scrollWheelZoom:true}).setView([20.5,78.9],5);const osm=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:' OpenStreetMap contributors'});osm.addTo(analyticsMap);analyticsMapLayers={};if(selectedArea?.geometry){const boundary=L.geoJSON(selectedArea.geometry,{style:{color:'#09ad86',weight:3,fillColor:'#1ab695',fillOpacity:.1}}).addTo(analyticsMap);analyticsMap.fitBounds(boundary.getBounds(),{padding:[20,20],maxZoom:14})}if(analyticsFeatures?.features?.length){const fc=L.geoJSON({type:'FeatureCollection',features:analyticsFeatures.features},{style:f=>({color:featureColor(f.properties.layer,f),weight:f.properties.layer==='drainage'?2:1,fillColor:featureColor(f.properties.layer,f),fillOpacity:.42}),pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:4,color:'#fff',weight:1,fillColor:featureColor(f.properties.layer,f),fillOpacity:.9}),onEachFeature:(f,l)=>l.bindPopup(`<b>${esc(f.properties.name||f.properties.category||'Mapped feature')}</b><br>${esc(f.properties.layer||'OpenStreetMap')}`)}).addTo(analyticsMap);analyticsMapLayers.features=fc}const markers=[];interventions.filter(x=>coordinateInSelectedArea(+x.lat,+x.lng)).forEach(x=>markers.push(L.circleMarker([+x.lat,+x.lng],{radius:7,color:'#fff',weight:1,fillColor:interventionColor(x.type),fillOpacity:1}).bindPopup(`<b>${esc(x.type)}</b><br>${esc(x.status||'')}<br>${esc(x.location||'')}`)));photoData.filter(x=>coordinateInSelectedArea(+x.lat,+x.lng)).forEach(x=>markers.push(L.marker([+x.lat,+x.lng]).bindPopup(`<div class="field-photo-popup"><img src="/api/uploads/${encodeURIComponent(x.filename)}"><b>${esc(x.location)}</b><span>${esc(x.taken_at||'')}</span></div>`)));markers.forEach(m=>m.addTo(analyticsMap));setTimeout(()=>analyticsMap.invalidateSize(),50)}
async function loadAnalyticsData(place){try{const [d,iv,pv]=await Promise.all([api(`/places/features?id=${encodeURIComponent(place.id)}&type=${encodeURIComponent(place.osm_type)}`),api('/interventions'),api('/photos')]);analyticsFeatures=d.data;interventions=iv.items||[];photoData=pv.items||[];analyticsLoadError='';header()}catch(e){analyticsFeatures=null;analyticsLoadError=e.message;toast(e.message)}renderAnalyticsResults()}
function renderAnalyticsResults(){const reportRoot=$('#report-results');if(reportRoot)reportRoot.innerHTML=reportContent();const root=$('#analytics-results');if(root)root.innerHTML=analyticsContent();const sub=$('#screen .page-head p');if(sub&&selectedArea)sub.textContent=`${selectedArea.display_name} | OpenStreetMap mapped features`;if($('#analytics-map')||$('#report-map'))initAnalyticsMap()}
async function searchAnalyticsArea(query,reportMode=false){const q=String(query||'').trim();if(!q)return toast('Enter a village, town, district or other mapped area.');const button=$(reportMode?'#report-search-btn':'#analytics-search-btn'),box=$(reportMode?'#report-area-results':'#analytics-area-results');if(button){button.disabled=true;button.textContent='Searching...'}try{const result=await api('/places/search?q='+encodeURIComponent(q));if(!result.items.length){box.innerHTML='<div class="state">No mapped administrative boundary found. Try a district, town or village.</div>';box.classList.remove('hidden');return}box.innerHTML='<b>Select the area to analyze</b>'+result.items.map((place,index)=>`<button class="area-result" data-analytics-area="${index}"><strong>${esc(place.name)}</strong><span>${esc(place.display_name)}</span></button>`).join('');box.classList.remove('hidden');box.querySelectorAll('[data-analytics-area]').forEach(b=>b.addEventListener('click',async()=>{selectedArea=result.items[Number(b.dataset.analyticsArea)];analyticsFeatures=null;analyticsLoadError='';box.classList.add('hidden');const sub=$('#screen .page-head p');if(sub)sub.textContent=`Loading OpenStreetMap features for ${selectedArea.display_name}...`;renderAnalyticsResults();await loadAnalyticsData(selectedArea)}))}catch(error){toast(error.message)}finally{if(button){button.disabled=false;button.textContent='Search area'}}}
async function searchMap(query){const q=String(query||'').trim();if(!q)return toast('Enter a village, town, district or other mapped area.');const button=$('#search-area');if(button){button.disabled=true;button.textContent='Searching...'}try{const result=await api('/places/search?q='+encodeURIComponent(q));const box=$('#area-results');if(!result.items.length){box.innerHTML='<div class="state">No mapped administrative boundary found. Try a district, town or watershed name.</div>';box.classList.remove('hidden');return}box.innerHTML='<b>Select the area to map</b>'+result.items.map((place,index)=>`<button class="area-result" data-area-index="${index}"><strong>${esc(place.name)}</strong><span>${esc(place.display_name)}</span></button>`).join('');box.classList.remove('hidden');box.querySelectorAll('[data-area-index]').forEach(b=>b.addEventListener('click',async()=>{selectedArea=result.items[Number(b.dataset.areaIndex)];analyticsFeatures=null;analyticsLoadError='';box.classList.add('hidden');await showSelectedArea(selectedArea)}))}catch(error){toast(error.message)}finally{if(button){button.disabled=false;button.textContent='Search area'}}}
document.addEventListener('keydown',e=>{if(e.target.id==='map-search'&&e.key==='Enter'){e.preventDefault();e.stopImmediatePropagation();searchMap(e.target.value)}},true);
document.addEventListener('click',e=>{const button=e.target.closest('[data-layer]');if(button&&button.parentElement.querySelector('span').textContent==='Thematic layer')button.dataset.layer=mapType},true);
function toggleLayer(b){let key=b.dataset.layer;if(!map||!mapLayers[key])return;const on=map.hasLayer(mapLayers[key]);if(on)map.removeLayer(mapLayers[key]);else mapLayers[key].addTo(map);b.classList.toggle('on',!on)}
async function initGalleryMap(el){if(!window.L)return;if(galleryMap){galleryMap.remove();galleryMap=null}galleryMap=L.map(el,{zoomControl:false}).setView([20.5,78.9],5);const osm=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:' OpenStreetMap contributors'});const sat=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Imagery  Esri, Maxar, Earthstar Geographics, and the GIS User Community'});sat.addTo(galleryMap);galleryBasemaps={map:osm,satellite:sat};L.control.layers({'Map':osm,'Satellite':sat},{},{collapsed:true}).addTo(galleryMap);if((current==='detail'||current==='trenching')&&activeIntervention){const lat=Number(activeIntervention.lat),lng=Number(activeIntervention.lng);L.circleMarker([lat,lng],{radius:8,color:'#fff',weight:2,fillColor:'#0aaf7b',fillOpacity:1}).addTo(galleryMap).bindPopup(esc(activeIntervention.type)).openPopup();galleryMap.setView([lat,lng],15);return}try{const d=await api('/photos');photoData=d.items||[];photoData.forEach(p=>{const marker=L.marker([Number(p.lat),Number(p.lng)]).addTo(galleryMap);marker.bindPopup(`<div class="field-photo-popup"><img src="/api/uploads/${encodeURIComponent(p.filename)}" alt="${esc(p.location)}"><b>${esc(p.location)}</b><span>${esc(p.taken_at||'')}</span></div>`)});if($('#photo-map-count'))$('#photo-map-count').textContent=photoData.length;if(photoData.length)galleryMap.fitBounds(L.latLngBounds(photoData.map(p=>[Number(p.lat),Number(p.lng)])),{padding:[20,20],maxZoom:14})}catch{if($('#photo-map-count'))$('#photo-map-count').textContent='Unavailable'}}
let leafletLoadPromise;
function ensureLeaflet(){if(window.L)return Promise.resolve();if(leafletLoadPromise)return leafletLoadPromise;leafletLoadPromise=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';css.onerror=()=>reject(Error('Map styles could not be loaded. Check your internet connection.'));document.head.appendChild(css);const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.onload=()=>window.L?resolve():reject(Error('Map library loaded without its API.'));script.onerror=()=>reject(Error('Map library could not be loaded. Check your internet connection.'));document.head.appendChild(script)});return leafletLoadPromise}
function renderMapFallback(el,zoom=5){if(!el)return;const lat=Number(selectedArea?.lat)||20.5,lng=Number(selectedArea?.lon)||78.9;const z=Math.max(2,Math.min(16,zoom)),n=2**z,x=(lng+180)/360*n,y=(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n,tiles=[];for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){const tx=((Math.floor(x)+dx)%n+n)%n,ty=Math.max(0,Math.min(n-1,Math.floor(y)+dy));tiles.push(`<img alt="" draggable="false" src="https://tile.openstreetmap.org/${z}/${tx}/${ty}.png" style="position:absolute;width:256px;height:256px;left:calc(50% + ${(Math.floor(x)+dx-x)*256}px);top:calc(50% + ${(Math.floor(y)+dy-y)*256}px)">`)}el.innerHTML=`<div class="tile-map-fallback" role="img" aria-label="OpenStreetMap centered on ${esc(selectedArea?.name||'India')}">${tiles.join('')}<span class="tile-map-marker" aria-hidden="true"></span><div class="tile-map-attribution">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a></div></div>`}
const initMapWithLeaflet=initMap;initMap=async function(el){try{await ensureLeaflet();await initMapWithLeaflet(el)}catch(e){renderMapFallback(el)}};
const initGalleryMapWithLeaflet=initGalleryMap;initGalleryMap=async function(el){try{await ensureLeaflet();await initGalleryMapWithLeaflet(el)}catch(e){renderMapFallback(el)}};
const initAnalyticsMapWithLeaflet=initAnalyticsMap;initAnalyticsMap=async function(){const el=$('#analytics-map')||$('#report-map');try{await ensureLeaflet();await initAnalyticsMapWithLeaflet()}catch(e){renderMapFallback(el)}};
function openIntervention(item){if(!item)return;activeIntervention=item;const photos=photoData.filter(p=>Number(p.intervention_id)===Number(item.id));$('#modal-root').innerHTML=`<div class="quick-modal" id="quick-modal"><div class="quick-box"><button class="close" id="close-modal"></button><span class="status-badge">${esc(item.status)}</span><h2>${esc(item.type)}</h2><div class="subtle">${esc(item.location)}  ${esc(item.date||'No date recorded')}</div><section class="detail-card" style="margin-top:12px"><h3>Coordinator site record</h3><p class="muted" style="font-size:10px">${esc(item.description||'No notes recorded.')}</p><div class="info-row"><span>GPS</span><b>${Number(item.lat).toFixed(5)}, ${Number(item.lng).toFixed(5)}</b></div><div class="info-row"><span>Linked photos</span><b>${photos.length}</b></div></section>${photos.length?`<div class="photo-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));margin-top:10px">${photos.slice(0,4).map(p=>`<article class="photo-card"><img src="/api/uploads/${encodeURIComponent(p.filename)}" alt="${esc(p.location)}"><div class="photo-meta">${esc(p.taken_at)}</div></article>`).join('')}</div>`:''}<a class="btn primary" style="margin-top:12px" href="#${item.type==='Contour Trenching'?'trenching':'detail'}">View site record</a></div></div>`;$('#close-modal').onclick=()=>$('#modal-root').innerHTML='';$('#quick-modal').onclick=e=>{if(e.target.id==='quick-modal')$('#modal-root').innerHTML=''}}
window.openInterventionById=id=>openIntervention(interventions.find(x=>x.id===id));
async function loadInterventions(){try{const d=await api('/interventions');interventions=d.items||[];const select=$('#photo-intervention');if(select)select.innerHTML='<option value="">No association</option>'+interventions.map(x=>`<option value="${x.id}">${esc(x.type)}  ${esc(x.location)} (${esc(x.status)})</option>`).join('')}catch(error){toast(error.message)}}
async function loadPhotos(){try{const d=await api('/photos');photoData=d.items||[];renderPhotos();await loadInterventions();if($('#gallery-map'))initGalleryMap($('#gallery-map'))}catch(e){$('#photo-grid').innerHTML=`<div class="state">${esc(e.message)}</div>`}}
function renderPhotos(filter=''){let list=photoData.filter(p=>`${p.location} ${p.description} ${p.taken_at}`.toLowerCase().includes(filter.toLowerCase()));$('#photo-count').textContent=`· ${list.length} photos`;$('#photo-grid').innerHTML=list.length?list.map(p=>`<article class="photo-card"><img src="/api/uploads/${encodeURIComponent(p.filename)}" alt="${esc(p.description||p.location)}"><div class="photo-meta"><strong>${esc(p.location)}</strong>${esc(p.taken_at)} · ${Number(p.lat).toFixed(4)}, ${Number(p.lng).toFixed(4)}<br>${esc(p.description||'Geotagged field photo')}${p.intervention?`<br><span class="status-badge">${esc(p.intervention)}</span>`:''}</div></article>`).join(''):'<div class="state" style="grid-column:1/-1">No uploaded photos yet. Coordinator users can add the first field photo.</div>'}
function bindPhotoForm(){const form=$('#photo-form');if(!form)return;const input=$('#photo-file'),zone=$('#dropzone');zone.addEventListener('click',e=>{if(e.target!==input)input.click()});input.addEventListener('change',previewFile);['dragenter','dragover'].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.add('drag')}));['dragleave','drop'].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.remove('drag')}));zone.addEventListener('drop',e=>{if(e.dataTransfer.files.length){input.files=e.dataTransfer.files;previewFile()}});form.addEventListener('submit',async e=>{e.preventDefault();const f=input.files[0];if(!f)return toast('Choose an image first.');if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>8*1024*1024)return toast('Use a JPG, PNG or WEBP image up to 8 MB.');const fd=new FormData(form);fd.delete('watershed');fd.set('intervention_id',fd.get('intervention_id')||'');try{const d=await fetch(API+'/photos',{method:'POST',body:fd,credentials:'same-origin'});const result=await d.json();if(!d.ok)throw Error(result.error||'Upload failed');toast('Photo saved with its GPS coordinates. View it on the intervention map.');form.reset();$('#preview').innerHTML='';await loadPhotos()}catch(err){toast(err.message)}})}
function bindInterventionForm(){const form=$('#intervention-form');if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(form));try{await api('/interventions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadInterventions();form.reset();toast('Intervention site saved to Coordinator field records.')}catch(error){toast(error.message)}})}
function previewFile(){let f=$('#photo-file').files[0];if(!f)return;const u=URL.createObjectURL(f);$('#preview').innerHTML=`<img src="${u}" style="display:block;max-width:150px;max-height:70px;object-fit:cover;margin:9px auto;border-radius:5px">`}
async function exportJSON(){if(!selectedArea||!analyticsFeatures)return toast('Select an area and wait for its data before exporting.');const report=buildAreaReport();const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`vasudha-${String(selectedArea.name||'area').toLowerCase().replace(/[^a-z0-9]+/g,'-')}-report.json`;a.click();URL.revokeObjectURL(a.href);toast('Selected area report exported.')}
function buildAreaReport(){const features=analyticsFeatures.features||[],count=layer=>features.filter(f=>f.properties.layer===layer),drain=count('drainage');return {generated_at:new Date().toISOString(),area:{name:selectedArea.name,display_name:selectedArea.display_name,osm_type:selectedArea.osm_type,osm_id:selectedArea.id,geometry:selectedArea.geometry,area_km2:geometryAreaKm2(selectedArea.geometry)},source:{boundary:'OpenStreetMap Nominatim',features:'OpenStreetMap Overpass API',attribution:'OpenStreetMap contributors',limit:1200},summary:{mapped_feature_count:features.length,land_use_count:count('landuse').length,vegetation_tag_count:count('vegetation').length,water_feature_count:count('water-bodies').length,drainage_feature_count:drain.length,drainage_length_km:drain.reduce((n,f)=>n+geometryLengthKm(f.geometry),0)},unavailable:['Soil moisture','Land degradation severity','Satellite vegetation indices','Time-series change','Intervention outcomes'],features}}
async function init(){try{const me=await api('/auth/me');viewer=me.user;const i=await api('/interventions');interventions=i.items}catch{}header();render();window.addEventListener('hashchange',()=>{if(map){map.remove();map=null}render()});window.addEventListener('resize',()=>{if(map)map.invalidateSize()})}
document.addEventListener('DOMContentLoaded',init);
